import base64,json,os,platform,socket,subprocess,time
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer

PORT=8765
START=time.monotonic()
HTML_B64=""""""

def html_bytes(): return base64.b64decode(HTML_B64)

def net():
    start=time.perf_counter()
    try:
        p=subprocess.run(["ping","-c","1","-W","2","1.1.1.1"],
            stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=4)
        latency=round((time.perf_counter()-start)*1000) if p.returncode==0 else None
    except Exception: latency=None
    try:
        s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM);s.settimeout(1)
        s.connect(("1.1.1.1",80));ip=s.getsockname()[0];s.close()
    except Exception: ip=None
    return latency,ip

class H(BaseHTTPRequestHandler):
    protocol_version="HTTP/1.1"
    def out(self,data,typ,status=200):
        try:
            self.send_response(status)
            self.send_header("Content-Type",typ)
            self.send_header("Content-Length",str(len(data)))
            self.send_header("Cache-Control","no-store,no-cache,must-revalidate")
            self.send_header("Pragma","no-cache")
            self.send_header("Connection","close")
            self.end_headers();self.wfile.write(data);self.wfile.flush()
        except (BrokenPipeError,ConnectionResetError,ConnectionAbortedError,TimeoutError): pass
    def js(self,x,status=200): self.out(json.dumps(x,ensure_ascii=False).encode(),"application/json; charset=utf-8",status)
    def do_GET(self):
        p=self.path.split("?",1)[0]
        if p in ("/","/index.html"): return self.out(html_bytes(),"text/html; charset=utf-8")
        if p=="/api/ping": return self.js({"ok":True,"ts":time.time()})
        if p=="/api/health": return self.js({"ok":True,"version":"V55-APK-FIXED","uptime_s":round(time.monotonic()-START,1),"python":platform.python_version(),"service":"foreground-sticky","mode":"read-only"})
        if p=="/api/status": return self.js({"ok":True,"pid":os.getpid(),"uptime_s":round(time.monotonic()-START,1),"service":"foreground-sticky"})
        if p=="/api/network":
            latency,ip=net()
            return self.js({"internet":latency is not None,"latency_ms":latency,"local_ip":ip})
        return self.js({"ok":False,"error":"not_found"},404)
    def log_message(self,*a): pass

server=ThreadingHTTPServer(("127.0.0.1",PORT),H)
server.daemon_threads=True
server.allow_reuse_address=True
server.serve_forever(.25)
